'use strict';

const fs = require('node:fs');
const net = require('node:net');
const { spawnSync } = require('node:child_process');

if (process.getuid() !== 65532) {
  throw new Error(`fixture expected uid 65532, received ${process.getuid()}`);
}

const status = fs.readFileSync('/proc/self/status', 'utf8');
const effectiveCapabilities = /^CapEff:\s*([0-9a-f]+)$/im.exec(status)?.[1];
if (!effectiveCapabilities || !/^0+$/.test(effectiveCapabilities)) {
  throw new Error(`fixture expected zero effective capabilities, received ${effectiveCapabilities || 'unknown'}`);
}

function expectDenied(operation, description) {
  try {
    operation();
  } catch (error) {
    if (error && (error.code === 'EACCES' || error.code === 'EPERM')) {
      return;
    }
    throw error;
  }
  throw new Error(`fixture unexpectedly ${description}`);
}

expectDenied(() => fs.readdirSync('/trace'), 'read the trace directory');
expectDenied(() => fs.writeFileSync('/trace/forged', 'forged'), 'wrote to the trace directory');

function attempt(operation) {
  try {
    operation();
  } catch (_) {
    // Expected inside the read only, offline test container.
  }
}

attempt(() => fs.readFileSync(`${process.env.HOME}/.ssh/id_rsa`, 'utf8'));
attempt(() => fs.writeFileSync('/etc/behaviorlock-should-not-exist', 'blocked'));
attempt(() => fs.writeFileSync('/work/behaviorlock-fixture-output', 'observed'));
attempt(() => spawnSync('/bin/sh', ['-c', 'true'], { timeout: 1000 }));

const socket = net.connect({ host: '198.51.100.1', port: 443 });
socket.on('error', () => process.exit(0));
socket.setTimeout(500, () => {
  socket.destroy();
  process.exit(0);
});
